use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    use core::fmt::Write;
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                let _ = write!(out, "%{:02X}", b);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment (platform-approved http-client grant): fetch one record for
        // this input on every call. RunInfo carries no `text` field, so the input's
        // text is taken as its date and start instant, joined by a space.
        // The result is deliberately discarded: the output must not depend on it.
        // A transport failure is a value from `fetch` and is ignored; a refused
        // (out-of-allowlist) request traps at the boundary as the host defines.
        let text = format!("{} {}", info.date, info.started);
        let url = format!("{}{}", ENRICH_BASE, encode_query(&text));
        let _ = http_client::fetch(&url);

        // Subscriptions: read the 'subscriptions' store under the key "urls",
        // stored as newline-separated URLs. A missing key yields an empty list.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
